using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed Discriminator property from documents.
            // Existing docs still have it, so keep it mapped for backward compat.
            entity.HasDiscriminator().IsComplete(false);

            // Breaking change 2: EF 9 uses raw key as "id" (e.g. "1") instead of
            // "Blog|1". Opt in to legacy format so existing documents are found.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB provider does not support indexes.
            // EF 9 now throws instead of silently ignoring. Removed HasIndex call.
        });
    }
}

// Breaking change 2 (cont.): value generator that reproduces the EF 8 "Type|Key" id format
// so the app can still read existing documents.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

